    def test_bind_nested_type_errors(self):
        batch, root = self.honest()
        guard = self.guard()
        chains = batch.chains
        proof = batch.proof
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(list(chains), 3, proof), root, b"s"
            )
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(("x",) * 3, 3, proof), root, b"s"
            )
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(chains, True, proof), root, b"s"
            )
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(chains, 3.0, proof), root, b"s"
            )
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(chains, 3, "proof"), root, b"s"
            )
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(
                    chains, 3, MerkleMultiProof(3, [0, 1, 2], ())
                ),
                root, b"s",
            )
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(
                    chains, 3, MerkleMultiProof(3, (0, 1, True), ())
                ),
                root, b"s",
            )
        with self.assertRaises(TypeError):
            guard.bind_once(
                BoundConsistencyChainBatch(
                    chains, 3, MerkleMultiProof(3, (0, 1, 2), (b"ok", 7))
                ),
                root, b"s",
            )
        chain = chains[0]
        first_segment = chain.proofs[0]
        bad_chain_cases = [
            dataclasses.replace(chain, roots=("root",)),
            dataclasses.replace(chain, proofs="p"),
            dataclasses.replace(
                chain,
                proofs=(
                    MerkleConsistencyProof(
                        True, first_segment.new_count, first_segment.nodes
                    ),
                )
                + chain.proofs[1:],
            ),
            dataclasses.replace(
                chain,
                proofs=(
                    MerkleConsistencyProof(
                        first_segment.old_count,
                        first_segment.new_count,
                        (b"node", 7),
                    ),
                )
                + chain.proofs[1:],
            ),
        ]
        for bad_chain in bad_chain_cases:
            with self.assertRaises(TypeError):
                guard.bind_once(
                    BoundConsistencyChainBatch(
                        (bad_chain,) + chains[1:], 3, proof
                    ),
                    root, b"s",
                )

