    def test_delegated_batch_rejection_does_not_consume(self):
        # the Merkle leaf commits the (tampered) chain, so the root passes;
        # the chain's own consistency proof is truncated and the batch fails
        chains = self._chains()
        segment = chains[0].proofs[0]
        broken_segment = MerkleConsistencyProof(
            segment.old_count, segment.new_count, segment.nodes[:-1]
        )
        broken_chain = dataclasses.replace(
            chains[0], proofs=(broken_segment,) + chains[0].proofs[1:]
        )
        batch, root = self.build([broken_chain] + chains[1:])
        guard = self.guard()
        binding = guard.bind_once(batch, root, b"s")
        self.assertFalse(guard.check(batch, root, binding, now=1))
        with self.assertRaises(ValueError):
            guard.bind_once(batch, root, b"s")

