        self.assertFalse(guard.check(batch[::-1], binding, now=1))
        self.assertFalse(guard.check(batch[:-1], binding, now=1))
        self.assertIn(b"s", guard._pending)
        self.assertTrue(guard.check(batch, binding, now=1))

